"""Built-in tones and ringtones (generated by scripts/gen_tones.py; regenerate, never hand-edit).

Handset tones are 8 kHz mono and go to the USB adapter while baresip is idle. Ringtones are
16 kHz mono and go to the base speaker through the headphone jack; each file is one 2 s "on"
burst and the ringer applies the 2 s / 4 s cadence. Uploaded ringtones live under
`<data_dir>/ringtones/<name>.wav` in the same format.
"""

from __future__ import annotations

import re
from pathlib import Path

SOUNDS_DIR = Path(__file__).parent

DIAL_TONE = SOUNDS_DIR / "dial_tone.wav"
CALL_ENDED = SOUNDS_DIR / "call_ended.wav"
ERROR = SOUNDS_DIR / "error.wav"

DEFAULT_RINGTONE = "classic"
BUILTIN_RINGTONES: dict[str, Path] = {
    "classic": SOUNDS_DIR / "ring_classic.wav",
    "chime": SOUNDS_DIR / "ring_chime.wav",
    "birds": SOUNDS_DIR / "ring_birds.wav",
}

RINGTONE_NAME = re.compile(r"[a-z0-9_-]{1,32}")
RINGTONE_RATE = 16000


def ringtones_dir(data_dir: Path) -> Path:
    return data_dir / "ringtones"


def uploaded_ringtone_path(name: str, data_dir: Path) -> Path | None:
    """Path of an uploaded ringtone, or None if the name is unsafe or nothing is there."""
    if not RINGTONE_NAME.fullmatch(name):
        return None
    path = ringtones_dir(data_dir) / f"{name}.wav"
    return path if path.is_file() else None


def ringtone_path(settings_or_name: object, data_dir: Path) -> Path:
    """Resolve a ringtone name (or a Settings object's `ringtone`) to a WAV on disk.

    Falls back to the built-in `classic` when the name is unknown or the file is gone: the phone
    must always ring with something (CLAUDE.md: never silence).
    """
    name = getattr(settings_or_name, "ringtone", settings_or_name)
    if isinstance(name, str):
        builtin = BUILTIN_RINGTONES.get(name)
        if builtin is not None and builtin.is_file():
            return builtin
        uploaded = uploaded_ringtone_path(name, data_dir)
        if uploaded is not None:
            return uploaded
    return BUILTIN_RINGTONES[DEFAULT_RINGTONE]


def ringtone_exists(name: str, data_dir: Path) -> bool:
    return name in BUILTIN_RINGTONES or uploaded_ringtone_path(name, data_dir) is not None
